<template>
  <section class="workbench" :class="{ embedded: isEmbedded }">
    <aside class="panel history-panel">
      <div class="panel-title"><h2>生成记录</h2><span>{{ history.length }}</span></div>
      <div class="actions"><button @click="reset">＋ 新建</button><button :disabled="!history.length" @click="toggleSelectAll">☑ 全选</button><button class="danger" :disabled="!selectedHistory.length" @click="removeSelected">⌫ 删除</button></div>
      <div v-if="history.length" class="history-list"><article v-for="item in history" :key="item.id" :class="{selected:selectedHistory.includes(item.id)}"><input v-model="selectedHistory" type="checkbox" :value="item.id"><button @click="restoreHistory(item)"><img :src="item.images[0]" alt="生成记录"><span>{{ item.prompt }}</span><small>{{ formatTime(item.createdAt) }}</small></button></article></div>
      <div v-else class="empty">暂无生成记录</div>
    </aside>

    <section class="panel generator-panel">
      <h1>生图工作台</h1>
      <div class="field-head"><strong>提示词</strong><div><RouterLink to="/canvas/prompts">▣ 查看提示词库</RouterLink><RouterLink to="/canvas/assets">▣ 查看我的素材</RouterLink></div></div>
      <textarea v-model="promptText" class="prompt-input" placeholder="描述画面主体、风格、构图、光线和用途"></textarea>
      <div class="field-head"><strong>参考图</strong><div><button @click="pasteReference">▣ 剪切板</button><button @click="referenceInput?.click()">↥ 上传</button></div></div>
      <div class="references" @click="referenceInput?.click()"><span v-if="!references.length">暂无参考图</span><figure v-for="(src,index) in references" :key="src" @click.stop><img :src="src" alt="参考图"><button title="移除参考图" @click="references.splice(index,1)">×</button></figure></div>
      <input ref="referenceInput" hidden type="file" accept="image/*" multiple @change="loadReferences">
      <label class="model-field"><strong>模型</strong><select v-model="model"><option v-for="item in modelOptions" :key="item">{{ item }}</option></select></label>
      <div class="option-field"><span>质量</span><div class="option-row"><button v-for="q in qualities" :key="q.value" :class="{active:quality===q.value}" @click="quality=q.value">{{ q.label }}</button></div></div>
      <div class="size-head"><span>尺寸</span><label>16倍数对齐 <input v-model="align16" type="checkbox"></label></div>
      <div class="dimensions"><label>W <input v-model.number="width" type="number" min="256" max="4096" step="16" @change="normalizeDimensions"></label><span>↔</span><label>H <input v-model.number="height" type="number" min="256" max="4096" step="16" @change="normalizeDimensions"></label></div>
      <div class="ratio-grid"><button v-for="item in sizes" :key="item.label" :class="{active:item.width===width&&item.height===height}" @click="applySize(item)">{{ item.label }}</button></div>
      <div class="option-field"><span>生成张数</span><div class="count-grid"><button v-for="n in 10" :key="n" :class="{active:count===n}" @click="count=n">{{ n }} 张</button></div></div>
      <button class="generate" :disabled="running||!promptText.trim()||!apiKey" @click="generate">{{ running?'正在生成…':'开始生成' }}</button>
      <p v-if="message" :class="{error:isError}">{{ message }}</p>
    </section>

    <section class="panel results-panel"><div class="panel-title"><h2>生成结果</h2><button v-if="images.length" @click="saveAll">下载全部</button></div><div v-if="images.length" class="result-grid"><figure v-for="(src,index) in images" :key="src"><img :src="src" :alt="`生成结果 ${index+1}`"><figcaption><button @click="download(src,index)">下载</button><button :disabled="savingAsset" @click="saveAsset(src,index)">{{ savingAsset?'保存中…':'存到素材库' }}</button></figcaption></figure></div><div v-else class="empty result-empty"><span>▧</span><strong>还没有生成图片</strong></div></section>
  </section>
</template>

<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import * as keysAPI from '@/api/keys'
import { buildGatewayUrl } from '@/api/url'
import { canvasStorage, makeId, type LibraryAsset } from './storage'

interface HistoryItem { id:string; prompt:string; images:string[]; createdAt:string }
interface SizePreset { label:string; width:number; height:number }
const HISTORY_KEY='jkapi_image_workbench_history_v1'
const SELECTED_API_KEY_STORAGE_KEY='jkapi_canvas_selected_api_key'
const promptText=ref(''), references=ref<string[]>([]), referenceInput=ref<HTMLInputElement|null>(null), model=ref('gpt-image-2'), quality=ref('auto'), count=ref(1), apiKey=ref(''), running=ref(false), savingAsset=ref(false), message=ref(''), isError=ref(false), images=ref<string[]>([]), history=ref<HistoryItem[]>([]), selectedHistory=ref<string[]>([]), align16=ref(true), width=ref(1024), height=ref(1024)
const route=useRoute()
const isEmbedded=computed(()=>route.query.embedded==='new-api')
const supportedImageModels=['gpt-image-2','gpt-image-1.5','gpt-image-1']
const availableModels=ref<string[]>([])
const qualities=[{value:'auto',label:'自动'},{value:'high',label:'高'},{value:'medium',label:'中'},{value:'low',label:'低'}]
const sizes:SizePreset[]=[{label:'1:1',width:1024,height:1024},{label:'3:2',width:1536,height:1024},{label:'2:3',width:1024,height:1536},{label:'4:3',width:1024,height:768},{label:'3:4',width:768,height:1024},{label:'16:9',width:1024,height:576},{label:'9:16',width:576,height:1024},{label:'1:1(2k)',width:2048,height:2048},{label:'16:9(2k)',width:2048,height:1152},{label:'9:16(2k)',width:1152,height:2048},{label:'16:9(4k)',width:4096,height:2304},{label:'9:16(4k)',width:2304,height:4096}]
const modelOptions=computed(()=>availableModels.value.length?availableModels.value:supportedImageModels)
function apiSize(){if(width.value===1024&&height.value===1024)return '1024x1024';if(width.value>height.value)return '1536x1024';if(height.value>width.value)return '1024x1536';return 'auto'}
function dataUrl(item:any){if(item?.b64_json)return `data:image/png;base64,${item.b64_json}`;return item?.url||''}
async function loadKeys(){try{const r=await keysAPI.list(1,100,{status:'active',sort_by:'created_at',sort_order:'desc'});const saved=localStorage.getItem(SELECTED_API_KEY_STORAGE_KEY)||'';const keys=r.items.filter(k=>k.group?.allow_image_generation||k.group?.name?.includes('生图')||k.group?.name?.includes('画布')||k.name.includes('生图')||k.name.includes('画布'));const key=keys.find(k=>String(k.id)===saved)||keys[0];if(key){apiKey.value=key.key;void loadAvailableModels(key.key)}}catch{message.value='未能加载生图密钥';isError.value=true}}
async function loadAvailableModels(key:string){try{const r=await fetch(buildGatewayUrl('/v1/models'),{headers:{Authorization:`Bearer ${key}`}});const p=await r.json().catch(()=>({}));if(!r.ok)throw new Error(p?.error?.message||p?.message||r.statusText);const models=(Array.isArray(p?.data)?p.data:[]).map((item:any)=>String(item?.id||'').trim()).filter((item:string)=>supportedImageModels.includes(item));availableModels.value=models.filter((item:string,index:number)=>models.indexOf(item)===index)}catch{availableModels.value=[]}}
function dataUrlBlob(value:string){const [meta,data]=value.split(',');const mime=meta.match(/data:([^;]+)/)?.[1]||'image/png';const binary=atob(data||'');const bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i+=1)bytes[i]=binary.charCodeAt(i);return new Blob([bytes],{type:mime})}
async function generate(){running.value=true;message.value='';isError.value=false;try{let r:Response;const size=apiSize();if(references.value.length){const form=new FormData();form.append('model',model.value);form.append('prompt',promptText.value);form.append('n',String(count.value));form.append('size',size);form.append('quality',quality.value);form.append('output_format','png');form.append('response_format','b64_json');references.value.forEach((src,index)=>form.append('image',dataUrlBlob(src),`reference-${index+1}.png`));r=await fetch(buildGatewayUrl('/v1/images/edits'),{method:'POST',headers:{Authorization:`Bearer ${apiKey.value}`},body:form})}else{r=await fetch(buildGatewayUrl('/v1/images/generations'),{method:'POST',headers:{Authorization:`Bearer ${apiKey.value}`,'Content-Type':'application/json'},body:JSON.stringify({model:model.value,prompt:promptText.value,n:count.value,size,quality:quality.value,output_format:'png',response_format:'b64_json'})})}const p=await r.json().catch(()=>({}));if(!r.ok)throw new Error(p?.error?.message||p?.message||r.statusText);images.value=(p.data||[]).map(dataUrl).filter(Boolean);if(!images.value.length)throw new Error('上游响应中没有图片');history.value.unshift({id:makeId('run'),prompt:promptText.value,images:images.value,createdAt:new Date().toISOString()});history.value=history.value.slice(0,20);persistHistory();message.value=`已生成 ${images.value.length} 张图片`}catch(e){message.value=`生成失败：${e instanceof Error?e.message:String(e)}`;isError.value=true}finally{running.value=false}}
function persistHistory(){localStorage.setItem(HISTORY_KEY,JSON.stringify(history.value))}
function readReference(file:File){if(!file.type.startsWith('image/'))return;const reader=new FileReader();reader.onload=()=>references.value.push(String(reader.result));reader.readAsDataURL(file)}
function loadReferences(e:Event){const files=[...((e.target as HTMLInputElement).files||[])].slice(0,10-references.value.length);files.forEach(readReference);(e.target as HTMLInputElement).value=''}
async function pasteReference(){try{for(const item of await navigator.clipboard.read()){const type=item.types.find(v=>v.startsWith('image/'));if(type){readReference(new File([await item.getType(type)],'clipboard.png',{type}));return}}message.value='剪切板中没有图片'}catch{message.value='无法读取剪切板图片';isError.value=true}}
function normalizeDimensions(){if(align16.value){width.value=Math.ceil(width.value/16)*16;height.value=Math.ceil(height.value/16)*16}width.value=Math.min(4096,Math.max(256,width.value));height.value=Math.min(4096,Math.max(256,height.value))}
function applySize(item:SizePreset){width.value=item.width;height.value=item.height}
function reset(){promptText.value='';references.value=[];images.value=[];message.value='';selectedHistory.value=[]}
function toggleSelectAll(){selectedHistory.value=selectedHistory.value.length===history.value.length?[]:history.value.map(v=>v.id)}
function removeSelected(){history.value=history.value.filter(v=>!selectedHistory.value.includes(v.id));selectedHistory.value=[];persistHistory()}
function restoreHistory(item:HistoryItem){promptText.value=item.prompt;images.value=item.images}
function download(src:string,index:number){const a=document.createElement('a');a.href=src;a.download=`canvas-image-${index+1}.png`;a.click()}
function saveAll(){images.value.forEach((src,i)=>setTimeout(()=>download(src,i),i*120))}
function isQuotaError(error:unknown){return error instanceof DOMException&&(error.name==='QuotaExceededError'||error.name==='NS_ERROR_DOM_QUOTA_REACHED')}
async function compactImageForLibrary(src:string){if(!src.startsWith('data:image/'))return src;const image=await new Promise<HTMLImageElement>((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('图片读取失败'));img.src=src});const naturalWidth=image.naturalWidth||image.width;const naturalHeight=image.naturalHeight||image.height;const maxSide=1024;const scale=Math.min(1,maxSide/Math.max(naturalWidth,naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(naturalWidth*scale));canvas.height=Math.max(1,Math.round(naturalHeight*scale));const ctx=canvas.getContext('2d');if(!ctx)return src;ctx.drawImage(image,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.82)}
async function saveAsset(src:string,index:number){if(savingAsset.value)return;savingAsset.value=true;message.value='';isError.value=false;try{const cover=await compactImageForLibrary(src);const assets=canvasStorage.assets();const item:LibraryAsset={id:makeId('asset'),type:'image',title:`生成图片 ${index+1}`,content:promptText.value,cover,tags:['AI生成'],source:'生图工作台',note:'',createdAt:new Date().toISOString()};assets.unshift(item);canvasStorage.saveAssets(assets.slice(0,80));message.value='已保存到我的素材'}catch(e){message.value=isQuotaError(e)?'保存失败：浏览器素材库空间不足，请先删除部分生成记录或素材后再试':`保存失败：${e instanceof Error?e.message:String(e)}`;isError.value=true}finally{savingAsset.value=false}}
function formatTime(v:string){return new Intl.DateTimeFormat('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(v))}
watch(modelOptions,(options)=>{if(options.length&&!options.includes(model.value))model.value=options[0]},{immediate:true})
onMounted(()=>{try{history.value=JSON.parse(localStorage.getItem(HISTORY_KEY)||'[]')}catch{history.value=[]}const pending=sessionStorage.getItem('jkapi_canvas_pending_prompt');if(pending){promptText.value=pending;sessionStorage.removeItem('jkapi_canvas_pending_prompt')}void loadKeys()})
</script>

<style scoped>
.workbench{display:grid;grid-template-columns:320px minmax(420px,1fr) minmax(390px,1.45fr);gap:12px;height:calc(100vh - 150px);min-height:610px}.workbench.embedded{height:calc(100vh - 42px)}.panel{min-width:0;border:1px solid #dce4ee;border-radius:8px;background:#fff;padding:16px;color:#1f2937;overflow:auto;box-shadow:0 10px 30px rgba(15,23,42,.05)}.panel-title,.field-head,.size-head{display:flex;align-items:center;justify-content:space-between;gap:12px}.panel-title h2,.generator-panel h1{margin:0;font-size:20px}.generator-panel h1{font-size:26px;margin-bottom:36px;color:#172033}.panel-title>span{padding:3px 9px;border-radius:4px;background:#edf3fb;color:#3a5a82;font-weight:700}.actions,.field-head>div{display:flex;gap:7px}.actions{margin:16px 0}.actions button,.field-head button,.field-head a,.panel-title button,.result-grid button{height:30px;padding:0 9px;border:1px solid #d8e1eb;border-radius:4px;background:#fff;color:#465569;font-size:13px}.field-head a{color:#2d6fd2}.actions button:hover,.field-head button:hover,.field-head a:hover,.panel-title button:hover,.result-grid button:hover{border-color:#9ec2f6;background:#f3f8ff}.actions button:disabled{opacity:.4}.danger{color:#c2410c!important}.empty{height:calc(100% - 80px);min-height:180px;border:1px dashed #ccd8e5;border-radius:7px;display:grid;place-content:center;color:#8a96a6;background:#fafcff}.history-list{display:grid;gap:8px}.history-list article{display:grid;grid-template-columns:auto 1fr;align-items:center;border:1px solid #e2e8f0;border-radius:5px;padding:7px}.history-list article.selected{border-color:#6fa7f2;background:#f4f8ff}.history-list article>button{border:0;background:transparent;color:inherit;display:grid;grid-template-columns:48px 1fr;gap:5px 8px;text-align:left}.history-list img{width:48px;height:48px;object-fit:cover;grid-row:span 2}.history-list span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.history-list small{color:#8390a0}.field-head{margin:18px 0 8px}.field-head a{display:inline-flex;align-items:center;text-decoration:none}.prompt-input{width:100%;height:164px;resize:none;border:1px solid #d6e0eb;border-radius:5px;background:#fbfdff;color:#1f2937;padding:12px;outline:none}.prompt-input:focus,.model-field select:focus,.dimensions input:focus{border-color:#72a9f6;box-shadow:0 0 0 3px rgba(18,103,247,.12)}.references{min-height:96px;border:1px dashed #c5d4e5;border-radius:6px;display:flex;align-items:center;justify-content:center;gap:8px;color:#8592a3;background:#fafcff;cursor:pointer;padding:8px}.references figure{position:relative;width:76px;height:76px;margin:0}.references img{width:100%;height:100%;object-fit:cover;border-radius:4px}.references figure button{position:absolute;right:2px;top:2px;border:0;border-radius:50%;width:20px;height:20px;background:#334155;color:#fff}.model-field,.option-field{display:grid;gap:9px;margin-top:18px}.model-field select{width:190px;height:36px;border:1px solid #d3ddea;border-radius:18px;background:#fff;color:#263447;padding:0 14px}.option-row,.count-grid,.ratio-grid{display:grid;gap:8px}.option-row{grid-template-columns:repeat(4,1fr)}.option-row button,.count-grid button,.ratio-grid button{height:36px;border:1px solid #d8e1eb;border-radius:18px;background:#fff;color:#536174}.option-row button.active,.count-grid button.active,.ratio-grid button.active{border-color:#1267f7;background:#eaf2ff;color:#1267f7;font-weight:700}.size-head{margin-top:18px}.size-head label{font-size:12px;color:#718096}.dimensions{display:flex;align-items:center;gap:8px;margin:9px 0}.dimensions label{display:flex;align-items:center;gap:5px}.dimensions input{width:92px;height:34px;border:1px solid #d6e0eb;background:#fff;color:#263447;border-radius:4px;padding:0 8px;outline:none}.ratio-grid{grid-template-columns:repeat(4,1fr)}.ratio-grid button,.count-grid button{border-radius:5px;font-size:12px}.count-grid{grid-template-columns:repeat(5,1fr)}.generate{width:100%;height:42px;margin-top:18px;border:0;border-radius:5px;background:#1267f7;color:#fff;font-weight:700;box-shadow:0 6px 14px rgba(18,103,247,.2)}.generate:disabled{background:#cbd5e1;color:#7b8796;box-shadow:none}.results-panel{display:flex;flex-direction:column}.result-empty{flex:1;margin-top:28px;text-align:center;gap:12px}.result-empty span{font-size:48px;color:#8eb8ef}.result-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:10px;margin-top:20px}.result-grid figure{margin:0;border:1px solid #dce4ee;border-radius:6px;overflow:hidden;background:#fff}.result-grid img{width:100%;aspect-ratio:1;object-fit:cover;display:block}.result-grid figcaption{display:flex;gap:6px;padding:7px}.generator-panel p{color:#16825d}.generator-panel p.error{color:#c2410c}@media(max-width:1200px){.workbench{grid-template-columns:240px minmax(400px,1fr);height:auto}.workbench.embedded{height:auto}.results-panel{grid-column:1/-1;min-height:420px}}@media(max-width:760px){.workbench{grid-template-columns:1fr}.results-panel{grid-column:auto}.panel{overflow:visible}.option-row,.ratio-grid{grid-template-columns:repeat(3,1fr)}}
</style>
